; (0 = unarmed; shr qword [rdx+8], 1 per call: k blind bites), [16] armed eat action, [17..63] 0.
; Parameters: K_CAP 16, k for enemy energy 1..2 = 1, QUIET_FEED_CAP 24, FRONT_FEED_CAP 48, REFILL_MIN 12,
